package server

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

var managedSQLParameter = regexp.MustCompile(`\$([0-9]+)\b`)

// All statements here are generated by the server; filter values remain bind
// arguments. Nested statements need disjoint placeholder numbers, not textual
// substitution of values into SQL.
func managedSQLShiftParameters(statement string, offset int) string {
	if offset == 0 {
		return statement
	}
	return managedSQLParameter.ReplaceAllStringFunc(statement, func(value string) string {
		n, _ := strconv.Atoi(value[1:])
		return "$" + strconv.Itoa(n+offset)
	})
}

// Independent dimension summaries cannot answer arbitrary joint filters. They
// can prove that one conjunct is absent, or every conjunct holds for every
// request. Mere presence in each marginal never proves a partial intersection.
type managedUsageDimensionFilter struct{ kind, value string }

func managedUsageConstantFilters(q managedLogQuery) (managedLogQuery, []managedUsageDimensionFilter, bool) {
	base := q
	filters := []managedUsageDimensionFilter{}
	for _, filter := range []managedUsageDimensionFilter{{"model", q.Model}, {"endpoint", q.Endpoint}, {"key", q.KeyID}, {"group", q.GroupID}} {
		if filter.value != "" {
			filters = append(filters, filter)
		}
	}
	base.Model, base.Endpoint, base.KeyID, base.GroupID = "", "", "", ""
	return base, filters, len(filters) > 0 && managedUsageRollupEligible(base)
}

func managedUsageConstantFilterSQL(q managedLogQuery, out managedUsageStats, rawSQL string, rawArgs []any) (string, []any, bool) {
	base, _, eligible := managedUsageConstantFilters(q)
	if !eligible {
		return rawSQL, rawArgs, false
	}
	guardSQL, guardArgs, _ := q.rollupFilterGateSQL()
	fastSQL, fastArgs := managedUsageRollupQuery(base, out)
	statement, args := managedUsageGuardedBranchesSQL(guardSQL, guardArgs, fastSQL, fastArgs, rawSQL, rawArgs)
	return statement, args, true
}

func managedUsageGuardedBranchesSQL(guardSQL string, guardArgs []any, fastSQL string, fastArgs []any, rawSQL string, rawArgs []any) (string, []any) {
	guardSQL = managedSQLShiftParameters(guardSQL, len(rawArgs))
	fastSQL = managedSQLShiftParameters(fastSQL, len(rawArgs)+len(guardArgs))
	args := append(append(append([]any{}, rawArgs...), guardArgs...), fastArgs...)
	// OFFSET 0 plus a lateral dependency ensures each expensive aggregate is
	// executed only when its proven case applies. All branches share one MVCC
	// statement snapshot; there is no race between checking and reading.
	statement := `WITH selection_guard AS MATERIALIZED (` + guardSQL + `)
 SELECT result.* FROM selection_guard g CROSS JOIN LATERAL (
 SELECT candidate.* FROM (` + fastSQL + `) candidate WHERE g.matched AND NOT g.different OFFSET 0
 ) result
 UNION ALL
 SELECT result.* FROM selection_guard g CROSS JOIN LATERAL (
 SELECT candidate.* FROM (` + rawSQL + `) candidate WHERE g.matched AND g.different OFFSET 0
 ) result`
	return statement, args
}

// The one-row result is (matched,different). This can also be joined by other
// retained readers to skip a provably empty selection. matched means every
// marginal is nonempty, not that their intersection has been established.
func (q managedLogQuery) rollupFilterGateSQL() (string, []any, bool) {
	base, filters, eligible := managedUsageConstantFilters(q)
	if !eligible {
		return "", nil, false
	}
	guardSQL, guardArgs := managedUsageDimensionGateSQL(base, filters)
	return guardSQL, guardArgs, true
}

func managedUsageDimensionGateSQL(base managedLogQuery, filters []managedUsageDimensionFilter) (string, []any) {
	// The guard does not need chart boundaries: it only proves the single-valued
	// dimension over exactly the selected timestamps/status, including unsafe
	// and incomplete minutes handled by the common retained source.
	base.Step = 0
	guardSQL, guardArgs := managedUsageRollupSourceWithMaterialization(base, false)
	matched, different, selected := []string{}, []string{}, []string{}
	for _, filter := range filters {
		guardArgs = append(guardArgs, filter.value)
		parameter := len(guardArgs)
		switch filter.kind {
		case "group":
			// Canonical dimensions deduplicate group membership per request.
			members := fmt.Sprintf("COALESCE(sum(requests) FILTER(WHERE kind='group' AND resource_id=$%d),0)", parameter)
			matched = append(matched, "("+members+">0)")
			different = append(different, "("+members+"<>COALESCE(sum(requests) FILTER(WHERE kind='total'),0))")
			selected = append(selected, fmt.Sprintf("kind='total' OR (kind='group' AND resource_id=$%d)", parameter))
		case "key":
			matched = append(matched, fmt.Sprintf("COALESCE(bool_or(kind='key' AND resource_id=$%d),false)", parameter))
			different = append(different, fmt.Sprintf("COALESCE(bool_or(kind='key_legacy' OR (kind='key' AND resource_id<>$%d)),false)", parameter))
			selected = append(selected, "kind IN ('key','key_legacy')")
		default:
			// kind is a fixed server enum, never caller-controlled SQL.
			matched = append(matched, fmt.Sprintf("COALESCE(bool_or(kind='%s' AND name=$%d),false)", filter.kind, parameter))
			different = append(different, fmt.Sprintf("COALESCE(bool_or(kind='%s' AND name<>$%d),false)", filter.kind, parameter))
			selected = append(selected, "kind='"+filter.kind+"'")
		}
	}
	guardSQL += " SELECT " + strings.Join(matched, " AND ") + " AS matched," + strings.Join(different, " OR ") + " AS different FROM source WHERE " + strings.Join(selected, " OR ")
	return guardSQL, guardArgs
}
